import sys
from collections import Counter

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    it = iter(data)

    N = next(it)
    dice = []
    sizes = []

    for _ in range(N):
        k = next(it)
        faces = [next(it) for _ in range(k)]
        dice.append(Counter(faces))
        sizes.append(k)

    ans = 0.0

    for i in range(N):
        for j in range(i + 1, N):
            if len(dice[i]) <= len(dice[j]):
                small, large = dice[i], dice[j]
            else:
                small, large = dice[j], dice[i]

            same_weight = 0
            for value, count in small.items():
                same_weight += count * large.get(value, 0)

            prob = same_weight / (sizes[i] * sizes[j])
            if prob > ans:
                ans = prob

    print(f"{ans:.15f}")

if __name__ == "__main__":
    main()
